SELECT ee.user_id originId, ee.employee_name referrerName, CASE WHEN ee.work_status = 0 THEN '试用' WHEN ee.work_status = 1 THEN '正式' WHEN ee.work_status = 2 THEN '离职' WHEN ee.work_status = 3 THEN '实习' ELSE '' END workStatus, bp.patientNumber, bp.receivedTotalWorkload, bp.freeTotalWorkload, bp.totalRefundAmount, bp.makeUpWorkload FROM base_employee ee INNER JOIN ( SELECT bp.origin_id, count(bp.origin_id) AS patientNumber, SUM(bb.received_amount) AS receivedTotalWorkload, SUM(bb.free_amount) AS freeTotalWorkload, SUM(br.refund_amount) AS totalRefundAmount, SUM(bbd.coupon_workload) AS makeUpWorkload FROM base_patient bp LEFT JOIN ( SELECT br.patient_id, SUM(br.refund_amount) AS refund_amount FROM base_refund br
